export function generateZip(country: string): string {
  const letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
  const digits = "0123456789";
  const randChar = (str: string) => str[Math.floor(Math.random() * str.length)];
  
  if (country === "SGP") {
    return Array.from({ length: 6 }, () => randChar(digits)).join("");
  } else if (country === "BRA") {
    const part1 = Array.from({ length: 5 }, () => randChar(digits)).join("");
    const part2 = Array.from({ length: 3 }, () => randChar(digits)).join("");
    return `${part1}-${part2}`;
  } else if (country === "AUS") {
    return Array.from({ length: 4 }, () => randChar(digits)).join("");
  } else if (country === "CAN") {
    return `${randChar(letters)}${randChar(digits)}${randChar(letters)} ${randChar(digits)}${randChar(letters)}${randChar(digits)}`;
  } else if (country === "JPN") {
    const part1 = Array.from({ length: 3 }, () => randChar(digits)).join("");
    const part2 = Array.from({ length: 4 }, () => randChar(digits)).join("");
    return `${part1}-${part2}`;
  } else if (country === "FRA" || country === "DEU") {
    return Array.from({ length: 5 }, () => randChar(digits)).join("");
  } else if (country === "GBR") {
    return `${randChar(letters)}${randChar(letters)}${randChar(digits)}${randChar(letters)} ${randChar(digits)}${randChar(letters)}${randChar(letters)}`;
  } else if (country === "IND") {
    return Array.from({ length: 6 }, () => randChar(digits)).join("");
  } else {
    return Array.from({ length: 5 }, () => randChar(digits)).join("");
  }
}
